    "lines": [
      {
        "text": "淒涼寶劍篇",
        "jyutping": ""
      },
      {
        "text": "羈泊欲窮年",
        "jyutping": ""
      },
      {
        "text": "黃葉仍風雨",
        "jyutping": ""
      },
      {
        "text": "青樓自管絃",
        "jyutping": ""
      },
      {
        "text": "新知遭薄俗",
        "jyutping": ""
      },
      {
        "text": "舊好隔良緣",
        "jyutping": ""
      },
      {
        "text": "心斷新豐酒",
        "jyutping": ""
      },
      {
        "text": "銷愁斗幾千",
        "jyutping": ""
      }
    ],
