      {
        "text": "遺言冀可冥",
        "jyutping": ""
      },
      {
        "text": "繕性何由熟",
        "jyutping": ""
      },
      {
        "text": "道人庭宇靜",
        "jyutping": ""
      },
      {
        "text": "苔色連深竹",
        "jyutping": ""
      },
      {
        "text": "日出霧露餘",
        "jyutping": ""
      },
      {
        "text": "青松如膏沐",
        "jyutping": ""
      },
      {
        "text": "澹然離言說",
        "jyutping": ""
      },
      {
        "text": "悟悅心自足",
        "jyutping": ""
      }
