    "jyutpingStatus": "未校對；可點詞查看粵典候選讀音",
    "lines": [
      {
        "text": "浮雲終日行",
        "jyutping": ""
      },
      {
        "text": "遊子久不至",
        "jyutping": ""
      },
      {
        "text": "三夜頻夢君",
        "jyutping": ""
      },
      {
        "text": "情親見君意",
        "jyutping": ""
      },
      {
        "text": "告歸常局促",
        "jyutping": ""
      },
      {
        "text": "苦道來不易",
        "jyutping": ""
      },
      {
        "text": "江湖多風波",
        "jyutping": ""
      },
      {
        "text": "舟楫恐失墜",
        "jyutping": ""
      },
      {
        "text": "出門搔白首",
        "jyutping": ""
      },
      {
        "text": "若負平生志",
        "jyutping": ""
      },
      {
        "text": "冠蓋滿京華",
        "jyutping": ""
      },
      {
        "text": "斯人獨顦顇",
        "jyutping": ""
      },
      {
        "text": "孰云網恢恢",
        "jyutping": ""
      },
      {
        "text": "將老身反累",
        "jyutping": ""
      },
      {
        "text": "千秋萬歲名",
        "jyutping": ""
      },
      {
        "text": "寂莫身後事",
        "jyutping": ""
      }
    ],
