    "collection": "唐詩三百首",
    "jyutpingStatus": "未校對；可點詞查看粵典候選讀音",
    "lines": [
      {
        "text": "花間一壺酒",
        "jyutping": ""
      },
      {
        "text": "獨酌無相親",
        "jyutping": ""
      },
      {
        "text": "舉杯邀明月",
        "jyutping": ""
      },
      {
        "text": "對影成三人",
        "jyutping": ""
      },
      {
        "text": "月既不解飲",
        "jyutping": ""
      },
      {
        "text": "影徒隨我身",
        "jyutping": ""
      },
      {
        "text": "暫伴月將影",
        "jyutping": ""
      },
      {
        "text": "行樂須及春",
        "jyutping": ""
      },
      {
        "text": "我歌月裴回",
        "jyutping": ""
      },
      {
        "text": "我舞影零亂",
        "jyutping": ""
      },
      {
        "text": "醒時同交歡",
        "jyutping": ""
      },
      {
        "text": "醉後各分散",
        "jyutping": ""
      },
      {
        "text": "永結無情遊",
        "jyutping": ""
      },
      {
        "text": "相期邈雲漢",
        "jyutping": ""
      }
    ],
    "annotation": "",
    "translation": "",
    "appreciation": "",
