    "lines": [
      {
        "text": "白日登山望烽火",
        "jyutping": ""
      },
      {
        "text": "昏黃飲馬傍交河",
        "jyutping": ""
      },
      {
        "text": "行人刁斗風砂暗",
        "jyutping": ""
      },
      {
        "text": "公主琵琶幽怨多",
        "jyutping": ""
      },
      {
        "text": "野營萬里無城郭",
        "jyutping": ""
      },
      {
        "text": "雨雪紛紛連大漠",
        "jyutping": ""
      },
      {
        "text": "胡雁哀鳴夜夜飛",
        "jyutping": ""
      },
      {
        "text": "胡兒眼淚雙雙落",
        "jyutping": ""
      },
      {
        "text": "聞道玉門猶被遮",
        "jyutping": ""
      },
      {
        "text": "應將性命逐輕車",
        "jyutping": ""
      },
      {
        "text": "年年戰骨埋荒外",
        "jyutping": ""
      },
      {
        "text": "空見蒲萄入漢家",
        "jyutping": ""
      }
    ],
