    "lines": [
      {
        "text": "長相思",
        "jyutping": ""
      },
      {
        "text": "在長安",
        "jyutping": ""
      },
      {
        "text": "絡緯秋啼金井欄",
        "jyutping": ""
      },
      {
        "text": "微霜淒淒簟色寒",
        "jyutping": ""
      },
      {
        "text": "孤燈不明思欲絕",
        "jyutping": ""
      },
      {
        "text": "卷帷望月空長歎",
        "jyutping": ""
      },
      {
        "text": "美人如花隔雲端",
        "jyutping": ""
      },
      {
        "text": "上有青冥之長天",
        "jyutping": ""
      },
      {
        "text": "下有綠水之波瀾",
        "jyutping": ""
      },
      {
        "text": "天長路遠魂飛苦",
        "jyutping": ""
      },
      {
        "text": "夢魂不到關山難",
        "jyutping": ""
      },
      {
        "text": "長相思",
        "jyutping": ""
      },
      {
        "text": "摧心肝",
        "jyutping": ""
      }
    ],
