    "collection": "宋詞三百首",
    "jyutpingStatus": "未校對；可點詞查看粵典候選讀音",
    "lines": [
      {
        "text": "濕雲黏雁影",
        "jyutping": ""
      },
      {
        "text": "望徵路愁迷",
        "jyutping": ""
      },
      {
        "text": "離緒難整",
        "jyutping": ""
      },
      {
        "text": "千金買光景",
        "jyutping": ""
      },
      {
        "text": "但疏鍾催曉",
        "jyutping": ""
      },
      {
        "text": "亂鴉啼暝",
        "jyutping": ""
      },
      {
        "text": "花暗省",
        "jyutping": ""
      },
      {
        "text": "許多情、相逢夢境",
        "jyutping": ""
      },
      {
        "text": "便行雲、都不歸來",
        "jyutping": ""
      },
      {
        "text": "也合寄將音信",
        "jyutping": ""
      },
      {
        "text": "孤迥",
        "jyutping": ""
      },
      {
        "text": "盟鸞心在",
        "jyutping": ""
      },
      {
        "text": "跨鶴程高",
        "jyutping": ""
      },
      {
        "text": "後期無準",
        "jyutping": ""
      },
      {
        "text": "情絲待翦",
        "jyutping": ""
      },
      {
        "text": "翻惹得",
        "jyutping": ""
      },
      {
        "text": "舊時恨",
        "jyutping": ""
      },
      {
        "text": "怕天教何處",
        "jyutping": ""
      },
      {
        "text": "參差雙燕",
        "jyutping": ""
      },
      {
        "text": "還染殘朱剩粉",
        "jyutping": ""
      },
      {
        "text": "對菱花、與説相思",
        "jyutping": ""
      },
      {
        "text": "看誰瘦損",
        "jyutping": ""
      }
    ],
    "annotation": "",
    "translation": "",
    "appreciation": "",
    "allusion": "",
    "isOpenCorpus": true
