    "lines": [
      {
        "text": "明月幾時有",
        "jyutping": ""
      },
      {
        "text": "把酒問青天",
        "jyutping": ""
      },
      {
        "text": "不知天上宮闕",
        "jyutping": ""
      },
      {
        "text": "今夕是何年",
        "jyutping": ""
      },
      {
        "text": "我欲乘風歸去",
        "jyutping": ""
      },
      {
        "text": "又恐瓊樓玉宇",
        "jyutping": ""
      },
      {
        "text": "高處不勝寒",
        "jyutping": ""
      },
      {
        "text": "起舞弄清影",
        "jyutping": ""
      },
      {
        "text": "何似在人間",
        "jyutping": ""
      },
      {
        "text": "轉朱閣",
        "jyutping": ""
      },
      {
        "text": "低綺户",
        "jyutping": ""
      },
      {
        "text": "照無眠",
        "jyutping": ""
      },
      {
        "text": "不應有恨",
        "jyutping": ""
      },
      {
        "text": "何事長向別時圓",
        "jyutping": ""
      },
      {
        "text": "人有悲歡離合",
        "jyutping": ""
      },
      {
        "text": "月有陰晴圓缺",
        "jyutping": ""
      },
      {
        "text": "此事古難全",
        "jyutping": ""
      },
      {
        "text": "但願人長久",
        "jyutping": ""
      },
      {
        "text": "千里共嬋娟",
        "jyutping": ""
      }
    ],
