      {
        "text": "雙闕中天",
        "jyutping": ""
      },
      {
        "text": "鳳樓十二春寒淺",
        "jyutping": ""
      },
      {
        "text": "去年元夜奉宸遊",
        "jyutping": ""
      },
      {
        "text": "曾侍瑤池宴",
        "jyutping": ""
      },
      {
        "text": "玉殿珠簾盡卷",
        "jyutping": ""
      },
      {
        "text": "擁羣仙、蓬壺閬苑",
        "jyutping": ""
      },
      {
        "text": "五雲深處",
        "jyutping": ""
      },
      {
        "text": "萬燭光中",
        "jyutping": ""
      },
      {
        "text": "揭天絲管",
        "jyutping": ""
      },
      {
        "text": "馳隙流年",
        "jyutping": ""
      },
      {
        "text": "恍如一瞬星霜換",
        "jyutping": ""
      },
      {
        "text": "今宵誰念泣孤臣",
        "jyutping": ""
      },
      {
        "text": "回首長安遠",
        "jyutping": ""
      },
      {
        "text": "可是塵緣未斷",
        "jyutping": ""
      },
      {
        "text": "謾惆悵、華胥夢短",
        "jyutping": ""
      },
      {
        "text": "滿懷幽恨",
        "jyutping": ""
      },
      {
        "text": "數點寒燈",
        "jyutping": ""
      },
      {
        "text": "幾聲歸雁",
        "jyutping": ""
      }
