    "collection": "宋詞三百首",
    "jyutpingStatus": "未校對；可點詞查看粵典候選讀音",
    "lines": [
      {
        "text": "臉霞紅印枕",
        "jyutping": ""
      },
      {
        "text": "睡覺來、冠兒還是不整",
        "jyutping": ""
      },
      {
        "text": "屏間麝煤冷",
        "jyutping": ""
      },
      {
        "text": "但眉峯壓翠",
        "jyutping": ""
      },
      {
        "text": "淚珠彈粉",
        "jyutping": ""
      },
      {
        "text": "堂深晝永",
        "jyutping": ""
      },
      {
        "text": "燕交飛、風簾露井",
        "jyutping": ""
      },
      {
        "text": "恨無人",
        "jyutping": ""
      },
      {
        "text": "與説相思",
        "jyutping": ""
      },
      {
        "text": "近日帶圍寬盡",
        "jyutping": ""
      },
      {
        "text": "重省",
        "jyutping": ""
      },
      {
        "text": "殘燈朱幌",
        "jyutping": ""
      },
      {
        "text": "淡月紗窗",
        "jyutping": ""
      },
      {
        "text": "那時風景",
        "jyutping": ""
      },
      {
        "text": "陽台路迥",
        "jyutping": ""
      },
      {
        "text": "雲雨夢",
        "jyutping": ""
      },
      {
        "text": "便無準",
        "jyutping": ""
      },
      {
        "text": "待歸來",
        "jyutping": ""
      },
      {
        "text": "先指花梢教看",
        "jyutping": ""
      },
      {
        "text": "卻把心期細問",
        "jyutping": ""
      },
      {
        "text": "問因循、過了青春",
        "jyutping": ""
      },
      {
        "text": "怎生意穩",
        "jyutping": ""
      }
    ],
