    "sourceRevision": "b8594f81a897",
    "collection": "宋詞三百首",
    "jyutpingStatus": "未校對；可點詞查看粵典候選讀音",
    "lines": [
      {
        "text": "天闊雲高",
        "jyutping": ""
      },
      {
        "text": "溪橫水遠",
        "jyutping": ""
      },
      {
        "text": "晚日寒生輕暈",
        "jyutping": ""
      },
      {
        "text": "閒階靜、楊花漸少",
        "jyutping": ""
      },
      {
        "text": "朱門掩、鶯聲猶嫩",
        "jyutping": ""
      },
      {
        "text": "悔匆匆、過卻清明",
        "jyutping": ""
      },
      {
        "text": "旋佔得餘芳",
        "jyutping": ""
      },
      {
        "text": "已成幽恨",
        "jyutping": ""
      },
      {
        "text": "都幾日陰沈",
        "jyutping": ""
      },
      {
        "text": "連宵慵困",
        "jyutping": ""
      },
      {
        "text": "起來韶華都盡",
        "jyutping": ""
      },
      {
        "text": "怨入雙眉閒鬥損",
        "jyutping": ""
      },
      {
        "text": "乍品得情懷",
        "jyutping": ""
      },
      {
        "text": "看承全近",
        "jyutping": ""
      },
      {
        "text": "深深態、無非自許",
        "jyutping": ""
      },
      {
        "text": "厭厭意、終羞人間",
        "jyutping": ""
      },
      {
        "text": "爭知道、夢裏蓬萊",
        "jyutping": ""
      },
      {
        "text": "待忘了餘香",
        "jyutping": ""
      },
      {
        "text": "時傳音信",
        "jyutping": ""
      },
      {
        "text": "縱留得鶯花",
        "jyutping": ""
      },
      {
        "text": "東風不住",
        "jyutping": ""
      },
      {
        "text": "也則眼前愁悶",
        "jyutping": ""
      }
    ],
    "annotation": "",
