    "lines": [
      {
        "text": "高詠楚詞酬午日",
        "jyutping": ""
      },
      {
        "text": "天涯節序匆匆",
        "jyutping": ""
      },
      {
        "text": "榴花不似舞裙紅",
        "jyutping": ""
      },
      {
        "text": "無人知此意",
        "jyutping": ""
      },
      {
        "text": "歌罷滿簾風",
        "jyutping": ""
      },
      {
        "text": "萬事一身傷老矣",
        "jyutping": ""
      },
      {
        "text": "戌葵凝笑牆東",
        "jyutping": ""
      },
      {
        "text": "酒杯深淺去年同",
        "jyutping": ""
      },
      {
        "text": "試澆橋下水",
        "jyutping": ""
      },
      {
        "text": "今夕到湘中",
        "jyutping": ""
      }
    ],
