      {
        "text": "漸吹盡、枝頭香絮",
        "jyutping": ""
      },
      {
        "text": "是處人家",
        "jyutping": ""
      },
      {
        "text": "綠深門户",
        "jyutping": ""
      },
      {
        "text": "遠浦縈迴",
        "jyutping": ""
      },
      {
        "text": "暮帆零亂向何許",
        "jyutping": ""
      },
      {
        "text": "閲人多矣",
        "jyutping": ""
      },
      {
        "text": "誰得似、長亭樹",
        "jyutping": ""
      },
      {
        "text": "樹若有情時",
        "jyutping": ""
      },
      {
        "text": "不會得、青青如此",
        "jyutping": ""
      },
      {
        "text": "日暮",
        "jyutping": ""
      },
      {
        "text": "望高城不見",
        "jyutping": ""
      },
      {
        "text": "只見亂山無數",
        "jyutping": ""
      },
      {
        "text": "韋郎去也",
        "jyutping": ""
      },
      {
        "text": "怎忘得、玉環分付",
        "jyutping": ""
      },
      {
        "text": "第一是、早早歸來",
        "jyutping": ""
      },
      {
        "text": "怕紅萼、無人為主",
        "jyutping": ""
      },
      {
        "text": "算空有並刀",
        "jyutping": ""
      },
      {
        "text": "難翦離愁千縷",
        "jyutping": ""
      }
