    "lines": [
      {
        "text": "月華收",
        "jyutping": ""
      },
      {
        "text": "雲淡霜天曙",
        "jyutping": ""
      },
      {
        "text": "西征客、此時情苦",
        "jyutping": ""
      },
      {
        "text": "翠娥執手送臨歧",
        "jyutping": ""
      },
      {
        "text": "軋軋開朱户",
        "jyutping": ""
      },
      {
        "text": "千嬌面、盈盈佇立",
        "jyutping": ""
      },
      {
        "text": "無言有淚",
        "jyutping": ""
      },
      {
        "text": "斷腸爭忍回顧",
        "jyutping": ""
      },
      {
        "text": "一葉蘭舟",
        "jyutping": ""
      },
      {
        "text": "便恁急槳凌波去",
        "jyutping": ""
      },
      {
        "text": "貪行色、豈知離緒",
        "jyutping": ""
      },
      {
        "text": "萬般方寸",
        "jyutping": ""
      },
      {
        "text": "但飲恨",
        "jyutping": ""
      },
      {
        "text": "脈脈同誰語",
        "jyutping": ""
      },
      {
        "text": "更回首、重城不見",
        "jyutping": ""
      },
      {
        "text": "寒江天外",
        "jyutping": ""
      },
      {
        "text": "隱隱兩三煙樹",
        "jyutping": ""
      }
    ],
