    "lines": [
      {
        "text": "傷高懷遠幾時窮",
        "jyutping": ""
      },
      {
        "text": "無物似情濃",
        "jyutping": ""
      },
      {
        "text": "離愁正引千絲亂",
        "jyutping": ""
      },
      {
        "text": "更東陌、飛絮",
        "jyutping": ""
      },
      {
        "text": "嘶騎漸遙",
        "jyutping": ""
      },
      {
        "text": "征塵不斷",
        "jyutping": ""
      },
      {
        "text": "何處認郎蹤",
        "jyutping": ""
      },
      {
        "text": "雙鴛池沼水溶溶",
        "jyutping": ""
      },
      {
        "text": "南北小橈通",
        "jyutping": ""
      },
      {
        "text": "梯橫畫閣黃昏後",
        "jyutping": ""
      },
      {
        "text": "又還是、斜月簾櫳",
        "jyutping": ""
      },
      {
        "text": "沈恨細思",
        "jyutping": ""
      },
      {
        "text": "不如桃杏",
        "jyutping": ""
      },
      {
        "text": "猶解嫁東風",
        "jyutping": ""
      }
    ],
