    "lines": [
      {
        "text": "一春長費買花錢",
        "jyutping": ""
      },
      {
        "text": "日日醉花邊",
        "jyutping": ""
      },
      {
        "text": "玉驄慣識西湖路",
        "jyutping": ""
      },
      {
        "text": "驕嘶過、沽酒壚前",
        "jyutping": ""
      },
      {
        "text": "紅杏香中簫鼓",
        "jyutping": ""
      },
      {
        "text": "綠楊影裏鞦韆",
        "jyutping": ""
      },
      {
        "text": "暖風十里麗人天",
        "jyutping": ""
      },
      {
        "text": "花壓髻雲偏",
        "jyutping": ""
      },
      {
        "text": "畫船載取春歸去",
        "jyutping": ""
      },
      {
        "text": "餘情寄、湖水湖煙",
        "jyutping": ""
      },
      {
        "text": "明日重扶殘醉",
        "jyutping": ""
      },
      {
        "text": "來尋陌上花鈿",
        "jyutping": ""
      }
    ],
