    "lines": [
      {
        "text": "月波疑滴",
        "jyutping": ""
      },
      {
        "text": "望玉壺天近",
        "jyutping": ""
      },
      {
        "text": "了無塵隔",
        "jyutping": ""
      },
      {
        "text": "翠眼圈花",
        "jyutping": ""
      },
      {
        "text": "冰絲織練",
        "jyutping": ""
      },
      {
        "text": "黃道寶光相直",
        "jyutping": ""
      },
      {
        "text": "自憐詩酒瘦",
        "jyutping": ""
      },
      {
        "text": "難應接、許多春色",
        "jyutping": ""
      },
      {
        "text": "最無賴",
        "jyutping": ""
      },
      {
        "text": "是隨香趁燭",
        "jyutping": ""
      },
      {
        "text": "曾伴狂客",
        "jyutping": ""
      },
      {
        "text": "蹤跡",
        "jyutping": ""
      },
      {
        "text": "謾記憶",
        "jyutping": ""
      },
      {
        "text": "老了杜郎",
        "jyutping": ""
      },
      {
        "text": "忍聽東風笛",
        "jyutping": ""
      },
      {
        "text": "柳院燈疏",
        "jyutping": ""
      },
      {
        "text": "梅廳雪在",
        "jyutping": ""
      },
      {
        "text": "誰與細傾春碧",
        "jyutping": ""
      },
      {
        "text": "舊情拘未定",
        "jyutping": ""
      },
      {
        "text": "猶自學、當年遊歷",
        "jyutping": ""
      },
      {
        "text": "怕萬一",
        "jyutping": ""
      },
      {
        "text": "誤玉人、夜寒簾隙",
        "jyutping": ""
      }
    ],
