    "lines": [
      {
        "text": "尋尋覓覓",
        "jyutping": ""
      },
      {
        "text": "冷冷清清",
        "jyutping": ""
      },
      {
        "text": "悽悽慘慘慼戚",
        "jyutping": ""
      },
      {
        "text": "乍暖還寒時候",
        "jyutping": ""
      },
      {
        "text": "最難將息",
        "jyutping": ""
      },
      {
        "text": "三杯兩盞淡酒",
        "jyutping": ""
      },
      {
        "text": "怎敵他、晚來風急",
        "jyutping": ""
      },
      {
        "text": "雁過也",
        "jyutping": ""
      },
      {
        "text": "正傷心",
        "jyutping": ""
      },
      {
        "text": "卻是舊時相識",
        "jyutping": ""
      },
      {
        "text": "滿地黃花堆積",
        "jyutping": ""
      },
      {
        "text": "憔悴損",
        "jyutping": ""
      },
      {
        "text": "如今有誰摘",
        "jyutping": ""
      },
      {
        "text": "守著窗兒",
        "jyutping": ""
      },
      {
        "text": "獨自怎生得黑",
        "jyutping": ""
      },
      {
        "text": "梧桐更兼細雨",
        "jyutping": ""
      },
      {
        "text": "到黃昏、點點滴滴",
        "jyutping": ""
      },
      {
        "text": "這次第",
        "jyutping": ""
      },
      {
        "text": "怎一個、愁字了得",
        "jyutping": ""
      }
    ],
