    "lines": [
      {
        "text": "枕簟溪堂冷欲秋",
        "jyutping": ""
      },
      {
        "text": "斷雲依水晚來收",
        "jyutping": ""
      },
      {
        "text": "紅蓮相倚渾如醉",
        "jyutping": ""
      },
      {
        "text": "白鳥無言定自愁",
        "jyutping": ""
      },
      {
        "text": "書咄咄",
        "jyutping": ""
      },
      {
        "text": "且休休",
        "jyutping": ""
      },
      {
        "text": "一丘一壑也風流",
        "jyutping": ""
      },
      {
        "text": "不知筋力衰多少",
        "jyutping": ""
      },
      {
        "text": "但覺新來懶上樓",
        "jyutping": ""
      }
    ],
