      {
        "text": "問春何苦匆匆",
        "jyutping": ""
      },
      {
        "text": "帶風伴雨如馳驟",
        "jyutping": ""
      },
      {
        "text": "幽葩細萼",
        "jyutping": ""
      },
      {
        "text": "小園低檻",
        "jyutping": ""
      },
      {
        "text": "壅培未就",
        "jyutping": ""
      },
      {
        "text": "吹盡繁紅",
        "jyutping": ""
      },
      {
        "text": "佔春長久",
        "jyutping": ""
      },
      {
        "text": "不如垂柳",
        "jyutping": ""
      },
      {
        "text": "算春常不老",
        "jyutping": ""
      },
      {
        "text": "人愁春老",
        "jyutping": ""
      },
      {
        "text": "愁只是、人間有",
        "jyutping": ""
      },
      {
        "text": "春恨十常八九",
        "jyutping": ""
      },
      {
        "text": "忍輕辜、芳醪經口",
        "jyutping": ""
      },
      {
        "text": "那知自是",
        "jyutping": ""
      },
      {
        "text": "桃花結子",
        "jyutping": ""
      },
      {
        "text": "不因春瘦",
        "jyutping": ""
      },
      {
        "text": "世上功名",
        "jyutping": ""
      },
      {
        "text": "老來風味",
        "jyutping": ""
      },
      {
        "text": "春歸時候",
        "jyutping": ""
      },
      {
        "text": "縱樽前痛飲",
        "jyutping": ""
      },
      {
        "text": "狂歌似舊",
        "jyutping": ""
      },
      {
        "text": "情難依舊",
        "jyutping": ""
      }
