      {
        "text": "淺醉還醒",
        "jyutping": ""
      },
      {
        "text": "愁不肯、與詩平",
        "jyutping": ""
      },
      {
        "text": "記長楸走馬",
        "jyutping": ""
      },
      {
        "text": "雕弓笮柳",
        "jyutping": ""
      },
      {
        "text": "前事休評",
        "jyutping": ""
      },
      {
        "text": "紫萸一枝傳賜",
        "jyutping": ""
      },
      {
        "text": "夢誰到、漢家陵",
        "jyutping": ""
      },
      {
        "text": "盡烏紗、便隨風去",
        "jyutping": ""
      },
      {
        "text": "要天知道",
        "jyutping": ""
      },
      {
        "text": "華髮如此星星",
        "jyutping": ""
      },
      {
        "text": "歌罷涕零",
        "jyutping": ""
      }
