      {
        "text": "忘卻舊遊端的",
        "jyutping": ""
      },
      {
        "text": "歡極",
        "jyutping": ""
      },
      {
        "text": "蓬壺蕖浸",
        "jyutping": ""
      },
      {
        "text": "花院梨溶",
        "jyutping": ""
      },
      {
        "text": "醉連春夕",
        "jyutping": ""
      },
      {
        "text": "柯雲罷弈",
        "jyutping": ""
      },
      {
        "text": "櫻桃在",
        "jyutping": ""
      },
      {
        "text": "夢難覓",
        "jyutping": ""
      },
      {
        "text": "勸清光",
        "jyutping": ""
      },
      {
        "text": "乍可幽窗相伴",
        "jyutping": ""
      },
      {
        "text": "休照紅樓夜笛",
        "jyutping": ""
      },
      {
        "text": "怕人間、換譜伊涼",
        "jyutping": ""
      },
      {
        "text": "素娥未識",
        "jyutping": ""
      }
