    "sourceRevision": "b8594f81a897",
    "collection": "宋詞三百首",
    "jyutpingStatus": "未校對；可點詞查看粵典候選讀音",
    "lines": [
      {
        "text": "洗妝真態",
        "jyutping": ""
      },
      {
        "text": "不作鉛華御",
        "jyutping": ""
      },
      {
        "text": "竹外一枝斜",
        "jyutping": ""
      },
      {
        "text": "想佳人、天寒日暮",
        "jyutping": ""
      },
      {
        "text": "黃昏小院",
        "jyutping": ""
      },
      {
        "text": "無處著清香",
        "jyutping": ""
      },
      {
        "text": "風細細",
        "jyutping": ""
      },
      {
        "text": "雪垂垂",
        "jyutping": ""
      },
      {
        "text": "何況江頭路",
        "jyutping": ""
      },
      {
        "text": "月邊疏影",
        "jyutping": ""
      },
      {
        "text": "夢到消魂處",
        "jyutping": ""
      },
      {
        "text": "結子欲黃時",
        "jyutping": ""
      },
      {
        "text": "又須著、廉纖細雨",
        "jyutping": ""
      },
      {
        "text": "孤芳一世",
        "jyutping": ""
      },
      {
        "text": "供斷有情愁",
        "jyutping": ""
      },
      {
        "text": "銷瘦卻",
        "jyutping": ""
      },
      {
        "text": "東陽也",
        "jyutping": ""
      },
      {
        "text": "試問花知否",
        "jyutping": ""
      }
    ],
    "annotation": "",
