    "lines": [
      {
        "text": "玉台掛秋月",
        "jyutping": ""
      },
      {
        "text": "鉛素淺",
        "jyutping": ""
      },
      {
        "text": "梅花傅香雪",
        "jyutping": ""
      },
      {
        "text": "冰姿潔",
        "jyutping": ""
      },
      {
        "text": "金蓮襯、小小凌波羅襪",
        "jyutping": ""
      },
      {
        "text": "雨初歇",
        "jyutping": ""
      },
      {
        "text": "樓外孤鴻聲漸遠",
        "jyutping": ""
      },
      {
        "text": "遠山外、行人音信絕",
        "jyutping": ""
      },
      {
        "text": "此恨對語猶難",
        "jyutping": ""
      },
      {
        "text": "那堪更寄書説",
        "jyutping": ""
      },
      {
        "text": "教人紅銷翠減",
        "jyutping": ""
      },
      {
        "text": "覺衣寬金縷",
        "jyutping": ""
      },
      {
        "text": "都為輕別",
        "jyutping": ""
      },
      {
        "text": "太情切",
        "jyutping": ""
      },
      {
        "text": "消魂處、畫角黃昏時節",
        "jyutping": ""
      },
      {
        "text": "聲嗚咽",
        "jyutping": ""
      },
      {
        "text": "落盡庭花春去也",
        "jyutping": ""
      },
      {
        "text": "銀蟾迥、無情圓又缺",
        "jyutping": ""
      },
      {
        "text": "恨伊不似餘香",
        "jyutping": ""
      },
      {
        "text": "惹鴛鴦結",
        "jyutping": ""
      }
    ],
